(()=>{const A=Abibi;if(!A.count()){location.replace('cart.html');return}if(!A.state.branch){location.replace('branches.html');return}const f=A.$('#checkout-form');let draft={};try{draft=JSON.parse(sessionStorage.getItem('abibi-checkout-v3')||'{}')}catch{}for(const n of ['customer','phone','address','note','timing','schedule'])if(draft[n])f.elements[n].value=draft[n];if(draft.mode)f.elements.mode.value=draft.mode;f.elements.customer.value ||= A.state.profile.name==='مهمان آبی‌بی'?'':A.state.profile.name;f.elements.phone.value ||= A.state.profile.phone;A.$('#saved-address').innerHTML+=[...A.state.addresses].map(x=>`<option value="${x.id}">${A.esc(x.title)}</option>`).join('');A.$('#saved-address').addEventListener('change',e=>{const x=A.state.addresses.find(a=>a.id===e.target.value);if(x)f.elements.address.value=x.text});function update(){const delivery=f.elements.mode.value==='delivery',scheduled=f.elements.timing.value==='scheduled';A.$('#delivery-fields').hidden=!delivery;f.elements.address.required=delivery;A.$('#schedule-label').hidden=!scheduled;f.elements.schedule.hidden=!scheduled;f.elements.schedule.required=scheduled;A.$('#checkout-summary').innerHTML=A.summary(f.elements.mode.value)}function persist(){const obj=Object.fromEntries(new FormData(f));sessionStorage.setItem('abibi-checkout-v3',JSON.stringify(obj))}f.addEventListener('change',()=>{update();persist()});f.addEventListener('input',persist);update();let submitted=false;f.addEventListener('abibi:valid-submit',e=>{e.preventDefault();if(submitted)return;const phone=A.digits(f.elements.phone.value).replace(/[\s-]/g,'');if(!/^09\d{9}$/.test(phone)){A.toast('شماره موبایل ۱۱ رقمی با ۰۹ وارد کن');f.elements.phone.focus();return}if(f.elements.timing.value==='scheduled'&&new Date(f.elements.schedule.value)<=new Date()){A.toast('زمانی در آینده انتخاب کن');return}submitted=true;const order={id:A.id(),number:String(Date.now()).slice(-7),date:new Date().toISOString(),branch:A.state.branch,items:A.state.cart.map(x=>({...x,unitPrice:A.unit(A.product(x.id)),originalPrice:A.product(x.id).price})),savings:A.subtotal()-A.sum(),total:A.sum()+(f.elements.mode.value==='delivery'?35000:0),mode:f.elements.mode.value,scheduled:f.elements.timing.value==='scheduled'?f.elements.schedule.value:null,status:'demo'};A.state.orders.unshift(order);A.state.cart=[];A.save();sessionStorage.removeItem('abibi-checkout-v3');location.href='success.html?id='+encodeURIComponent(order.id)})})();
